#!/usr/bin/env python3
# -*- coding: utf-8 -*-
from pathlib import Path
import base64, sys
ROOT = Path(__file__).resolve().parent
if not (ROOT / "frontend" / "src").is_dir():
    print("ERROR: jalankan skrip ini dari root repo faqbot-v2")
    sys.exit(1)
FILES = {
    'frontend/src/main.tsx': '',
    'frontend/src/EndUserApp.tsx': '',
    'frontend/src/features/enduser/EndUserAuthGate.tsx': '',
}
for rel, b64 in FILES.items():
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    data = base64.b64decode(b64)
    path.write_bytes(data)
    print("OK  %s (%d bytes)" % (path, len(data)))
print()
main = (ROOT / "frontend/src/main.tsx").read_text(encoding="utf-8")
if "EndUserAuthGate" not in main:
    print("WARNING: main.tsx belum mengandung EndUserAuthGate")
    sys.exit(2)
print("Cek OK: main.tsx mengandung EndUserAuthGate")
print("Selesai. Jalankan: git status")
